contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 1000000000000000000); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function check(uint256 x) public {
        c.AdjustDifficulty(x); if (__ESBMC_reverted()) return;
        uint256 got = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        assert(got == x);
    }
}

