pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function _check(uint256 x) internal {
        try c.AdjustDifficulty(x) {} catch { return; }
        uint256 got;
        try c.currentDifficulty() returns (uint256 __r) { got = __r; } catch { return; }
        assertTrue(got == x);
    }

    function testFuzz_check(uint256 x) public {
        _check(x);
    }

    receive() external payable {}
}
